const input = $input.first().json;
const body = input.body || input;

const isTelegram = !!input.message;
const message = isTelegram
  ? (input.message?.text || '')
  : (body.message || body.query || body.text || '');
const userId = isTelegram
  ? String(input.message?.from?.id || 'telegram-user')
  : (body.user_id || 'demo-user');
const chatId = isTelegram
  ? String(input.message?.chat?.id || '')
  : (body.chat_id || '');

if (!message && !body.intent) {
  throw new Error('Missing message or intent. Send: { "message": "Find me ML jobs in NYC" }');
}

const directIntent = body.intent || null;
const directEntities = body.entities || {};

return [{ json: {
  user_id: userId,
  chat_id: chatId,
  message: message,
  direct_intent: directIntent,
  direct_entities: directEntities,
  demo_mode: body.demo_mode !== false,
  session_id: body.session_id || `sess_${userId}_${Date.now()}`,
  source: isTelegram ? 'telegram' : 'webhook',
  received_at: new Date().toISOString()
}}];

const d = $input.first().json;

const mockSession = {
  history: [],
  context: {
    last_company: null,
    last_role: 'Senior ML Engineer',
    last_location: 'New York, NY',
    last_jd_url: null
  }
};

return [{ json: {
  ...d,
  session_history: mockSession.history,
  session_context: mockSession.context
}}];

const d = $input.first().json;
return [{ json: {
  ...d,
  routing: {
    intent: d.direct_intent,
    branch: d.direct_intent,
    entities: d.direct_entities,
    confidence: 1.0,
    reasoning: 'Direct intent provided by caller'
  }
}}];

const r = $input.first().json;
const content = r.choices?.[0]?.message?.content || '{}';
let routing = {};
try { routing = JSON.parse(content); } catch(e) {
  routing = { intent: 'find_jobs', branch: 'find_jobs', entities: {}, confidence: 0.7, reasoning: 'Defaulting to job discovery' };
}
const prevData = $('💾 Load Session Memory').first().json;
return [{ json: { ...prevData, routing } }];

const d = $input.first().json;
return [{ json: {
  user_id: d.user_id,
  role: d.routing.entities.target_role || d.session_context.last_role || 'Senior ML Engineer',
  location: d.routing.entities.location || d.session_context.last_location || 'New York, United States',
  keywords: d.routing.entities.keywords || ['Python', 'LLM', 'AI'],
  remote: true,
  demo_mode: d.demo_mode,
  session_id: d.session_id,
  _pipeline_stage: 'job_discovery'
}}];

const jobResult = $input.first().json;
const data = jobResult.data || jobResult;
const topJob = (data.top_jobs || [])[0] || {};
const prevInput = $('⚡ Full Pipeline — Prep').first().json;

return [{ json: {
  user_id: prevInput.user_id,
  company_name: topJob.company || 'Target Company',
  target_role: topJob.title || prevInput.role,
  channel: 'email',
  demo_mode: prevInput.demo_mode,
  session_id: prevInput.session_id,
  _top_job: topJob,
  _pipeline_stage: 'company_intel'
}}];

const intelResult = $input.first().json;
const intelData = intelResult.data || intelResult;
const topJob = $('🏆 Pipeline — Extract Top Job').first().json._top_job || {};
const prevInput = $('⚡ Full Pipeline — Prep').first().json;

return [{ json: {
  user_id: prevInput.user_id,
  jd_url: topJob.url || '',
  target_role: topJob.title || prevInput.role,
  target_company: intelData.company || topJob.company || '',
  company_intel: {
    brief: intelData.brief,
    talking_points: intelData.talking_points,
    health_score: intelData.health_score
  },
  demo_mode: prevInput.demo_mode,
  session_id: prevInput.session_id,
  _pipeline_stage: 'application_forge'
}}];

const forgeResult = $input.first().json;
const forgeData = forgeResult.data || forgeResult;
const jobData = $('🔍 Pipeline — Find Jobs').first().json;
const intelData = $('🏢 Pipeline — Company Intel').first().json;
const prevInput = $('⚡ Full Pipeline — Prep').first().json;

return [{ json: {
  status: 'success',
  branch: 'full_pipeline',
  session_id: prevInput.session_id,
  jobs_found: (jobData.data || jobData).jobs_found || 0,
  top_job: (jobData.data || jobData).top_jobs?.[0],
  company_health: (intelData.data || intelData).health_score,
  company_brief: (intelData.data || intelData).brief,
  forge_score: (forgeData.data || forgeData).forge_score,
  tailored_resume: (forgeData.data || forgeData).tailored_resume,
  cover_letter: (forgeData.data || forgeData).cover_letter,
  generated_at: new Date().toISOString()
}}];

const judgeResult = $input.first().json;
const content = judgeResult.choices?.[0]?.message?.content || '{}';
let judgment = {};
try { judgment = JSON.parse(content); } catch(e) {
  judgment = { passed: true, confidence: 0.9, issues: [], warnings: [], verdict: 'Output looks good.' };
}

const branchResult = $('🔀 Collect Branch Results').first().json;

return [{ json: {
  ...branchResult,
  validation: judgment,
  final_status: judgment.passed ? 'success' : 'success_with_warnings',
  warnings: judgment.warnings || []
}}];

const d = $input.first().json;
console.log('Session updated:', d.session_id, d.branch || d.final_status);
return [{ json: d }];
